#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
# 取り消した後も、ヘッダ行と他の予約（kaede の行）は残る
grep -qxF "$(printf '# room\tdate\tstart\tend\twho')" "$t" || { echo "header line lost"; fail=1; }
grep -qxF "$(printf 'kaede\t2026-01-05\t13:00\t14:00\ty')" "$t" || { echo "other booking lost"; fail=1; }
# 一致しない予約: exit 1、メッセージは stderr、stdout は空
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
[ $rc = 1 ] || { echo "not found should exit 1, got $rc"; fail=1; }
[ -z "$out" ] || { echo "not found should print nothing on stdout: $out"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null | grep -qxF 'not found: aoi 2026-01-05 11:00' || { echo "not found message missing on stderr"; fail=1; }
# 引数の数が違う: exit 2、usage は stderr、stdout は空
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>/dev/null); rc=$?
[ $rc = 2 ] || { echo "usage should exit 2, got $rc"; fail=1; }
[ -z "$out" ] || { echo "usage should print nothing on stdout: $out"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null | grep -qxF 'usage: cancel.sh ROOM DATE START' || { echo "usage message missing on stderr"; fail=1; }
rm -f "$t"

